//! Loads the bundled Albion combat dataset.
//!
//! The three JSON files are compiled into the binary with `include_str!` and parsed once on first
//! use, exactly like `openalbion::service`'s catalog and ability loaders. Nothing is fetched at
//! runtime: the dataset is regenerated by hand after an Albion patch with
//! `python3 scripts/generate_albion_combat_data.py`.
//!
//! A parse failure panics rather than degrading. The data ships inside the binary, so a failure
//! here is a build-time mistake that every request would hit, not a runtime condition worth
//! threading an error through the Item Power calculator for.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use super::data_types::{CombatItem, CombatRules, DatasetVersion, SpecNode};

/// Every equippable base, keyed by tier-stripped identifier (`2H_POLEHAMMER`).
///
/// The key matches `openalbion::service::base_identifier`, so an item persisted on a build row
/// resolves through the same string the ability catalog is keyed by.
pub fn combat_items() -> &'static BTreeMap<String, CombatItem> {
    static ITEMS: OnceLock<BTreeMap<String, CombatItem>> = OnceLock::new();
    ITEMS.get_or_init(|| {
        serde_json::from_str(include_str!("data/items.json"))
            .expect("bundled combat items.json must be valid")
    })
}

/// Every spell reachable from an equippable item, keyed by its Albion spell id.
///
/// Left as raw JSON on purpose. Phase 0 bundles the numbers; the simulator is what decides how to
/// type an effect tree, and typing it before then would be guessing at a shape nothing reads yet.
pub fn combat_spells() -> &'static BTreeMap<String, serde_json::Value> {
    static SPELLS: OnceLock<BTreeMap<String, serde_json::Value>> = OnceLock::new();
    SPELLS.get_or_init(|| {
        serde_json::from_str(include_str!("data/spells.json"))
            .expect("bundled combat spells.json must be valid")
    })
}

/// The global tables: quality, progression, Destiny Board rules and combat modifiers.
pub fn combat_rules() -> &'static CombatRules {
    static RULES: OnceLock<CombatRules> = OnceLock::new();
    RULES.get_or_init(|| {
        serde_json::from_str(include_str!("data/rules.json"))
            .expect("bundled combat rules.json must be valid")
    })
}

/// Which ao-bin-dumps commit the bundled dataset came from.
pub fn dataset_version() -> &'static DatasetVersion {
    &combat_rules().dataset_version
}

/// Looks up one base identifier's combat record.
#[must_use]
pub fn combat_item(base: &str) -> Option<&'static CombatItem> {
    combat_items().get(base)
}

/// Looks up one Destiny Board node.
#[must_use]
pub fn spec_node(node: &str) -> Option<&'static SpecNode> {
    combat_rules().spec_nodes.get(node)
}

#[cfg(test)]
mod dataset_invariant_tests {
    use super::{combat_item, combat_items, combat_rules, combat_spells, dataset_version};
    use crate::modules::combat::pattern;

    /// The tiers the generator emits, and the only ones the app offers.
    const TIERS: std::ops::RangeInclusive<u8> = 4..=8;

    #[test]
    fn the_dataset_parses_and_is_not_empty() {
        assert!(combat_items().len() > 200, "expected the full equippable catalog");
        assert!(combat_spells().len() > 1000, "expected the reachable spell closure");
        assert!(combat_rules().spec_nodes.len() > 200, "expected the combat Destiny Board");
    }

    #[test]
    fn the_dumps_commit_is_a_sha() {
        let commit = &dataset_version().dumps_commit;
        assert_eq!(commit.len(), 40, "dumps commit {commit} is not a full SHA");
        assert!(commit.chars().all(|c| c.is_ascii_hexdigit()));
    }

    #[test]
    fn quality_bonuses_match_the_game() {
        let rules = combat_rules();
        assert!((rules.quality_bonus(1) - 0.0).abs() < f64::EPSILON);
        assert!((rules.quality_bonus(2) - 20.0).abs() < f64::EPSILON);
        assert!((rules.quality_bonus(3) - 40.0).abs() < f64::EPSILON);
        assert!((rules.quality_bonus(4) - 60.0).abs() < f64::EPSILON);
        assert!((rules.quality_bonus(5) - 100.0).abs() < f64::EPSILON);
    }

    #[test]
    fn an_unknown_quality_contributes_nothing() {
        assert!((combat_rules().quality_bonus(9) - 0.0).abs() < f64::EPSILON);
    }

    #[test]
    fn a_known_weapon_has_the_item_power_the_game_shows() {
        let polehammer = combat_item("2H_POLEHAMMER").expect("polehammer is in the catalog");
        assert_eq!(polehammer.item_power_at(8, 0), Some(1100));
        assert_eq!(polehammer.item_power_at(8, 2), Some(1300));
        assert_eq!(polehammer.item_power_at(8, 4), Some(1500));
        assert_eq!(polehammer.item_power_at(4, 0), Some(700));
        assert!(polehammer.two_handed);
        assert_eq!(polehammer.progression.as_deref(), Some("mainhand_2h"));
        assert_eq!(polehammer.spec_node.as_deref(), Some("COMBAT_HAMMERS_POLE"));
    }

    #[test]
    fn every_enchantment_step_is_a_hundred_item_power() {
        for (base, item) in combat_items() {
            for (tier, ladder) in &item.item_power {
                if ladder.iter().all(|value| *value == ladder[0]) {
                    continue; // Artifacts and the like cannot be enchanted at all.
                }
                for pair in ladder.windows(2) {
                    assert_eq!(
                        pair[1] - pair[0],
                        100,
                        "{base} T{tier}: enchantment step {pair:?} is not 100"
                    );
                }
            }
        }
    }

    #[test]
    fn every_item_resolves_to_a_progression_row() {
        let rules = combat_rules();
        for (base, item) in combat_items() {
            let Some(progression) = item.progression.as_deref() else {
                continue; // Bags and capes declare no progression type.
            };
            assert!(
                rules.item_power_progression.contains_key(progression),
                "{base}: progression {progression} has no row"
            );
        }
    }

    #[test]
    fn every_item_spec_node_exists() {
        let rules = combat_rules();
        for (base, item) in combat_items() {
            if let Some(node) = item.spec_node.as_deref() {
                assert!(rules.spec_nodes.contains_key(node), "{base}: unknown node {node}");
            }
        }
    }

    #[test]
    fn every_specialization_has_a_known_parent_mastery() {
        let rules = combat_rules();
        for (id, node) in &rules.spec_nodes {
            if node.kind == "spec" {
                let parent = node.parent.as_deref().unwrap_or_else(|| panic!("{id} has no parent"));
                assert!(rules.spec_nodes.contains_key(parent), "{id}: unknown parent {parent}");
            }
        }
    }

    #[test]
    fn every_destiny_pattern_matches_a_real_item() {
        let names: Vec<String> = combat_items()
            .keys()
            .flat_map(|base| TIERS.map(move |tier| pattern::unique_name(tier, base)))
            .collect();
        for (id, node) in &combat_rules().spec_nodes {
            let patterns: Vec<&str> =
                node.bonuses.iter().flat_map(|rule| &rule.patterns).map(String::as_str).collect();
            assert!(
                patterns.iter().any(|glob| names.iter().any(|name| pattern::matches(glob, name))),
                "{id}: none of {patterns:?} matches any catalog item"
            );
        }
    }

    #[test]
    fn the_destiny_bonuses_are_the_ones_the_game_grants() {
        let node = combat_rules().spec_nodes.get("COMBAT_HAMMERS_POLE").expect("node exists");
        let own = node
            .bonuses
            .iter()
            .find(|rule| rule.patterns.iter().any(|p| p == "T?_2H_POLEHAMMER"))
            .expect("the node grants its own weapon");
        assert!((own.bonus - 2.0).abs() < f64::EPSILON, "own-item bonus is +2.0 per level");
        assert_eq!((own.min_tier, own.max_tier), (4, 8));

        let family = node
            .bonuses
            .iter()
            .find(|rule| rule.patterns.iter().any(|p| p.ends_with('*')))
            .expect("the node also grants its family");
        assert!((family.bonus - 0.2).abs() < f64::EPSILON, "family bonus is +0.2 per level");
    }

    #[test]
    fn the_armour_pieces_carry_the_whole_hit_point_pool() {
        let shares = &combat_rules().stat_shares;
        let armour: f64 = ["head", "armor", "shoes"]
            .iter()
            .filter_map(|slot| shares.hitpoints.get(*slot))
            .sum();
        assert!((armour - 1.0).abs() < 1e-9, "head+armor+shoes should pool one character's hit points");
        assert!((shares.armor.get("armor").copied().unwrap_or_default() - 1.0).abs() < 1e-9);
        assert_eq!(shares.hitpoints.get("mainhand").copied(), Some(0.0));
    }

    #[test]
    fn the_base_character_matches_the_game() {
        let defaults = &combat_rules().character_defaults;
        assert!((defaults.hitpoints_max - 1200.0).abs() < f64::EPSILON);
        assert!((defaults.energy_max - 120.0).abs() < f64::EPSILON);
        assert!((combat_rules().global_cast_delay - 0.5).abs() < f64::EPSILON);
    }

    #[test]
    fn the_combat_modifier_tables_are_loaded() {
        let rules = combat_rules();
        assert_eq!(rules.aoe_escalation.threshold_max, 7, "area escalation caps at 7 targets");
        assert!((rules.focus_fire.lookback_seconds - 10.0).abs() < f64::EPSILON);
        assert!(rules.focus_fire.attackers.len() > 20);
        assert_eq!(rules.zerg_debuff.allies.first().map(|row| row.at_least), Some(21));
        assert!((rules.cc_diminishing_returns.max - 0.8).abs() < f64::EPSILON);
    }
}
